const OnboardingFeature={id:"onboarding",name:"Onboarding",icon:"waving_hand",route:!1,data:{advisorName:"",trade:"window_coverings",weeklyTarget:600,businessAddress:"",distanceUnit:"miles",measurementUnit:"mm"},init(){},render(){return`\n      <div class="fade-in minh-screen flex flex-col" >\n        <div class="flex-1 pad-scroll" >\n          <div class="fs-40 mb-sm" >👋</div>\n          <h1 class="fs-26 fw-700 mb-sm" >Welcome to AdvisorOS</h1>\n          <p class="text-secondary mb-28 lh-150" >\n            It adapts to you — you don't adapt to it. Everything below can be changed later in Settings, so don't overthink it.\n          </p>\n\n          <div class="form-group">\n            <label>Your Full Name *</label>\n            <input type="text" class="input" id="ob-name" placeholder="e.g. Riaz Ahmed" value="${Utils.escapeHtml(this.data.advisorName)}">\n          </div>\n\n          <div class="form-group">\n            <label>Your Trade</label>\n            <select class="select" id="ob-trade">\n              ${CONFIG.trades.map(e=>`<option value="${e.id}" ${this.data.trade===e.id?"selected":""}>${e.name}</option>`).join("")}\n            </select>\n          </div>\n\n          <div class="divider-text mt-28" >Weekly Target</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            Powers your morning brief — how far you are from target, and whether you can afford to discount a job.\n          </p>\n          <div class="form-group">\n            <label>Weekly Net Earnings Goal (£)</label>\n            <input type="number" class="input fs-24 fw-700 text-center" inputmode="decimal" id="ob-target" placeholder="600" value="${this.data.weeklyTarget}" step="10" min="0" >\n          </div>\n          <div class="flex gap-sm" >\n            ${[400,600,800,1e3].map(e=>`\n              <button type="button" class="btn btn-outline btn-sm flex-1"  onclick="OnboardingFeature.setTargetPreset(${e})">£${e}</button>\n            `).join("")}\n          </div>\n\n          <div class="divider-text mt-28" >Home / Business Base</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            Powers route distances, ETAs, mileage tax relief, and the weather glance on Home. Optional — leave blank and add it later if you'd rather.\n          </p>\n          <div class="form-group">\n            <textarea class="textarea" id="ob-address" placeholder="e.g. 12 Example Street, Manchester M14 7FZ" style="min-height:70px;">${Utils.escapeHtml(this.data.businessAddress||"")}</textarea>\n          </div>\n\n          <div class="divider-text mt-28" >Distance Unit</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            UK mileage tax relief is calculated in miles: 55p/mile for the first 10,000 business miles (2026/27).\n          </p>\n          <div class="segmented" id="ob-distance-segmented">\n            <button type="button" class="segment ${"miles"===this.data.distanceUnit?"active":""}" data-value="miles" onclick="OnboardingFeature.setUnit('distanceUnit', 'miles', 'ob-distance-segmented')">Miles</button>\n            <button type="button" class="segment ${"km"===this.data.distanceUnit?"active":""}" data-value="km" onclick="OnboardingFeature.setUnit('distanceUnit', 'km', 'ob-distance-segmented')">Kilometres</button>\n          </div>\n\n          <div class="divider-text mt-28" >Measurement Unit</div>\n          <p class="text-secondary fs-13 mb-md lh-150" >\n            Used when you measure a window for blinds/curtains on a visit.\n          </p>\n          <div class="segmented" id="ob-measurement-segmented">\n            <button type="button" class="segment ${"mm"===this.data.measurementUnit?"active":""}" data-value="mm" onclick="OnboardingFeature.setUnit('measurementUnit', 'mm', 'ob-measurement-segmented')">mm</button>\n            <button type="button" class="segment ${"cm"===this.data.measurementUnit?"active":""}" data-value="cm" onclick="OnboardingFeature.setUnit('measurementUnit', 'cm', 'ob-measurement-segmented')">cm</button>\n            <button type="button" class="segment ${"inches"===this.data.measurementUnit?"active":""}" data-value="inches" onclick="OnboardingFeature.setUnit('measurementUnit', 'inches', 'ob-measurement-segmented')">in</button>\n          </div>\n\n          <button class="btn btn-primary btn-block mt-xl"  onclick="OnboardingFeature.finish()">\n            Start Using AdvisorOS <span class="material-symbols-rounded">check</span>\n          </button>\n\n          <button class="btn btn-outline btn-block mt-10"  onclick="OnboardingFeature.importBackup()">\n            <span class="material-symbols-rounded">restore</span>\n            Restore Backup Instead\n          </button>\n          <input type="file" id="ob-import-file" accept=".json,application/json" style="display:none;" onchange="OnboardingFeature.handleImport(event)">\n        </div>\n      </div>\n    `},setTargetPreset(e){this.data.weeklyTarget=e;const t=document.getElementById("ob-target");t&&(t.value=e)},setUnit(e,t,a){this.data[e]=t;const n=document.getElementById(a);n&&n.querySelectorAll(".segment").forEach(e=>{e.classList.toggle("active",e.dataset.value===t)})},importBackup(){const e=document.getElementById("ob-import-file");e&&e.click()},async handleImport(e){const t=e.target.files[0];if(t)try{await ExportService.importBackup(t),Toast.show("Backup restored","success"),App.navigate("today")}catch(e){console.error("Onboarding import failed:",e),Toast.show("Import failed: "+(e.message||"Please check the backup file"),"error")}finally{e.target.value=""}},async finish(){const e=document.getElementById("ob-name"),t=document.getElementById("ob-trade"),a=document.getElementById("ob-target"),n=document.getElementById("ob-address");if(this.data.advisorName=e?e.value.trim():this.data.advisorName,this.data.trade=t?t.value:this.data.trade,this.data.weeklyTarget=a?parseFloat(a.value)||600:this.data.weeklyTarget,this.data.businessAddress=n?n.value.trim():this.data.businessAddress,!this.data.advisorName)return Toast.show("Please enter your name","error"),e?.scrollIntoView({behavior:"smooth",block:"center"}),void e?.focus();CONFIG.advisorName=this.data.advisorName,CONFIG.trade=this.data.trade,CONFIG.weeklyTarget=this.data.weeklyTarget,CONFIG.businessAddress=this.data.businessAddress,CONFIG.distanceUnit=this.data.distanceUnit,CONFIG.measurementUnit=this.data.measurementUnit;const s={advisorName:CONFIG.advisorName,trade:CONFIG.trade,weeklyTarget:CONFIG.weeklyTarget,businessAddress:CONFIG.businessAddress,distanceUnit:CONFIG.distanceUnit,measurementUnit:CONFIG.measurementUnit,advisorMode:CONFIG.advisorMode,country:CONFIG.country,currency:CONFIG.currency,taxSystem:CONFIG.taxSystem,dateFormat:CONFIG.dateFormat,onboardingComplete:!0};localStorage.setItem("advisoros_config",JSON.stringify(s));try{await DB.setSetting("config",s)}catch(e){}Toast.show(`Welcome, ${CONFIG.advisorName}!`,"success"),App.navigate("today")}};App.registerFeature(OnboardingFeature);
